    if (i >= 0) {
        int j = n - 1;
        while (a[j] <= a[i]) j--;                      // rightmost value bigger than the pivot
        swap(a[i], a[j]);
    }
    reverse(a.begin() + i + 1, a.end());               // smallest arrangement of the suffix
